#include <stdlib.h>
#include <string.h>
#include <omp.h>

#define MR 6
#define NR 16
#define KC 256
#define MC 72
#define NB 256

typedef float v8 __attribute__((vector_size(32)));
typedef float v8u __attribute__((vector_size(32), aligned(4)));

static void *amalloc(size_t bytes)
{
    size_t sz = (bytes + 63) & ~(size_t)63;
    if (sz == 0) sz = 64;
    return aligned_alloc(64, sz);
}

/* Compute a 6x16 tile: acc = Ap(6 x kc) * Bp(kc x 16). */
static inline void kernel(int kc, const float *restrict a, const float *restrict b,
                          float *restrict c, int ldc, int mr, int nr, int accum)
{
    v8 c00 = {0}, c01 = {0}, c10 = {0}, c11 = {0}, c20 = {0}, c21 = {0};
    v8 c30 = {0}, c31 = {0}, c40 = {0}, c41 = {0}, c50 = {0}, c51 = {0};

    for (int k = 0; k < kc; k++) {
        v8 b0 = *(const v8 *)(b);
        v8 b1 = *(const v8 *)(b + 8);
        v8 a0 = (v8){0} + a[0];
        c00 += a0 * b0; c01 += a0 * b1;
        v8 a1 = (v8){0} + a[1];
        c10 += a1 * b0; c11 += a1 * b1;
        v8 a2 = (v8){0} + a[2];
        c20 += a2 * b0; c21 += a2 * b1;
        v8 a3 = (v8){0} + a[3];
        c30 += a3 * b0; c31 += a3 * b1;
        v8 a4 = (v8){0} + a[4];
        c40 += a4 * b0; c41 += a4 * b1;
        v8 a5 = (v8){0} + a[5];
        c50 += a5 * b0; c51 += a5 * b1;
        a += MR;
        b += NR;
    }

    if (mr == MR && nr == NR) {
#define STORE_ROW(r, x0, x1)                                   \
        do {                                                   \
            v8u *p0 = (v8u *)(c + (r) * ldc);                  \
            v8u *p1 = (v8u *)(c + (r) * ldc + 8);              \
            if (accum) { *p0 += x0; *p1 += x1; }               \
            else { *p0 = x0; *p1 = x1; }                       \
        } while (0)
        STORE_ROW(0, c00, c01);
        STORE_ROW(1, c10, c11);
        STORE_ROW(2, c20, c21);
        STORE_ROW(3, c30, c31);
        STORE_ROW(4, c40, c41);
        STORE_ROW(5, c50, c51);
#undef STORE_ROW
    } else {
        float t[MR * NR] __attribute__((aligned(64)));
        *(v8 *)(t + 0 * NR) = c00; *(v8 *)(t + 0 * NR + 8) = c01;
        *(v8 *)(t + 1 * NR) = c10; *(v8 *)(t + 1 * NR + 8) = c11;
        *(v8 *)(t + 2 * NR) = c20; *(v8 *)(t + 2 * NR + 8) = c21;
        *(v8 *)(t + 3 * NR) = c30; *(v8 *)(t + 3 * NR + 8) = c31;
        *(v8 *)(t + 4 * NR) = c40; *(v8 *)(t + 4 * NR + 8) = c41;
        *(v8 *)(t + 5 * NR) = c50; *(v8 *)(t + 5 * NR + 8) = c51;
        for (int i = 0; i < mr; i++)
            for (int j = 0; j < nr; j++) {
                if (accum) c[i * ldc + j] += t[i * NR + j];
                else c[i * ldc + j] = t[i * NR + j];
            }
    }
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;

    int npanels = (n + NR - 1) / NR;
    float *Bp = (float *)amalloc((size_t)KC * npanels * NR * sizeof(float));
    int nib = (n + MC - 1) / MC;
    int njb = (n + NB - 1) / NB;

    #pragma omp parallel
    {
        float *Ap = (float *)amalloc((size_t)MC * KC * sizeof(float));

        for (int pc = 0; pc < n; pc += KC) {
            int kc = n - pc < KC ? n - pc : KC;
            int accum = pc > 0;

            /* Pack B[pc:pc+kc, :] into column panels of width NR. */
            #pragma omp for schedule(static)
            for (int jp = 0; jp < npanels; jp++) {
                float *dst = Bp + (size_t)jp * NR * kc;
                int j0 = jp * NR;
                int w = n - j0 < NR ? n - j0 : NR;
                for (int k = 0; k < kc; k++) {
                    const float *src = B + (size_t)(pc + k) * n + j0;
                    float *d = dst + (size_t)k * NR;
                    if (w == NR) {
                        memcpy(d, src, NR * sizeof(float));
                    } else {
                        int j;
                        for (j = 0; j < w; j++) d[j] = src[j];
                        for (; j < NR; j++) d[j] = 0.0f;
                    }
                }
            }

            #pragma omp for collapse(2) schedule(dynamic, 1)
            for (int ib = 0; ib < nib; ib++) {
                for (int jb = 0; jb < njb; jb++) {
                    int ic = ib * MC;
                    int mc = n - ic < MC ? n - ic : MC;
                    int jc = jb * NB;
                    int nc = n - jc < NB ? n - jc : NB;

                    /* Pack A[ic:ic+mc, pc:pc+kc] into row panels of height MR. */
                    int mpan = (mc + MR - 1) / MR;
                    for (int p = 0; p < mpan; p++) {
                        float *dst = Ap + (size_t)p * MR * kc;
                        int r0 = p * MR;
                        int h = mc - r0 < MR ? mc - r0 : MR;
                        const float *src = A + (size_t)(ic + r0) * n + pc;
                        if (h == MR) {
                            for (int k = 0; k < kc; k++) {
                                float *d = dst + k * MR;
                                d[0] = src[k];
                                d[1] = src[n + k];
                                d[2] = src[2 * (size_t)n + k];
                                d[3] = src[3 * (size_t)n + k];
                                d[4] = src[4 * (size_t)n + k];
                                d[5] = src[5 * (size_t)n + k];
                            }
                        } else {
                            for (int k = 0; k < kc; k++) {
                                float *d = dst + k * MR;
                                int r;
                                for (r = 0; r < h; r++) d[r] = src[(size_t)r * n + k];
                                for (; r < MR; r++) d[r] = 0.0f;
                            }
                        }
                    }

                    for (int j = 0; j < nc; j += NR) {
                        int nr = nc - j < NR ? nc - j : NR;
                        const float *bp = Bp + (size_t)((jc + j) / NR) * NR * kc;
                        for (int p = 0; p < mpan; p++) {
                            int r0 = p * MR;
                            int mr = mc - r0 < MR ? mc - r0 : MR;
                            kernel(kc, Ap + (size_t)p * MR * kc, bp,
                                   C + (size_t)(ic + r0) * n + jc + j, n,
                                   mr, nr, accum);
                        }
                    }
                }
            }
        }

        free(Ap);
    }

    free(Bp);
}
```
Observation: Compiled and passed the correctness checks.
Runtime: 9.8 ms.
Speedup versus the naive triple loop: 212.39x.
Feedback: **What limits this attempt (9.8 ms, about 200 GFLOP/s at n≈1000)**

1. **Barriers and C traffic per K-block.** With KC=256 there are about 4 `pc` iterations, each with two `omp for` barriers. Each one also re-reads and re-writes all of C. Fix: use KC ≈ 384–512, or give each thread a C block and loop K inside it with no barriers.

2. **A is packed redundantly.** The same A block is packed once for each of the `njb` (≈4) column blocks. The 6-row strided gather is also slow and not vectorized. Fix: pack each A block once per `(ib, pc)` and reuse it for all `jb`, or pack A in parallel up front like B.

3. **Too few, uneven tasks.** There are only about 14×4 = 56 dynamic tasks, and the edge tiles are smaller, so many-core machines see imbalance and scheduler overhead. Fix: choose MC/NC from the thread count, e.g. 2D-partition C into exactly `nthreads` × k chunks with `schedule(static)`.

4. **Kernel width is fixed at AVX2.** Under `#ifdef __AVX512F__`, use 64-byte vectors with a 14×32 or 12×32 tile. That doubles peak; the current 6×16 code wastes AVX-512 hardware.

5. **Small fixes:**
   - Prefetch the next A/B micro-panels and the C rows before the kernel stores.
   - Unroll k by 4.
   - Pad `ldc` stores to avoid 4K aliasing when n is a power of two.

6. **Flags:** add `-ffast-math`, and consider `-fno-trapping-math`.

