        FOR_ROWS(FMA)
#undef FMA
        a += MR;
        b += NR;
    }

    if (mr == MR && nr == NR) {
        if (accum) {
#define ST(i) { VU *p = (VU *)(c + (size_t)(i) * ldc); p[0] += c##i##0; \
