#include <stdlib.h>
#include <string.h>
#include <omp.h>
#include <immintrin.h>

#ifdef __AVX512F__
#define VW 16
#define MR 12
#define NR 32
#define MCP 8
#define NCP 2
#else
#define VW 8
#define MR 6
#define NR 16
#define MCP 16
#define NCP 4
#endif
#define KCMAX 1024

typedef float V __attribute__((vector_size(VW * 4)));
typedef float VU __attribute__((vector_size(VW * 4), aligned(4)));

#if MR == 12
#define FOR_ROWS(M) M(0) M(1) M(2) M(3) M(4) M(5) M(6) M(7) M(8) M(9) M(10) M(11)
#else
#define FOR_ROWS(M) M(0) M(1) M(2) M(3) M(4) M(5)
#endif

static float *sA = 0, *sB = 0;
static size_t capA = 0, capB = 0;

static float *grow(float *p, size_t *cap, size_t need)
{
    if (need <= *cap) return p;
    free(p);
    size_t sz = (need * sizeof(float) + 4095) & ~(size_t)4095;
    p = (float *)aligned_alloc(4096, sz);
    *cap = sz / sizeof(float);
    return p;
}

#ifdef __AVX__
/* Load 8 floats from each of 8 rows at column k and transpose: o[j] = column k+j. */
static inline void tr8(const float *const *rows, int k, __m256 o[8])
{
    __m256 r0 = _mm256_loadu_ps(rows[0] + k), r1 = _mm256_loadu_ps(rows[1] + k);
    __m256 r2 = _mm256_loadu_ps(rows[2] + k), r3 = _mm256_loadu_ps(rows[3] + k);
    __m256 r4 = _mm256_loadu_ps(rows[4] + k), r5 = _mm256_loadu_ps(rows[5] + k);
    __m256 r6 = _mm256_loadu_ps(rows[6] + k), r7 = _mm256_loadu_ps(rows[7] + k);
    __m256 t0 = _mm256_unpacklo_ps(r0, r1), t1 = _mm256_unpackhi_ps(r0, r1);
    __m256 t2 = _mm256_unpacklo_ps(r2, r3), t3 = _mm256_unpackhi_ps(r2, r3);
    __m256 t4 = _mm256_unpacklo_ps(r4, r5), t5 = _mm256_unpackhi_ps(r4, r5);
    __m256 t6 = _mm256_unpacklo_ps(r6, r7), t7 = _mm256_unpackhi_ps(r6, r7);
    __m256 u0 = _mm256_shuffle_ps(t0, t2, 0x44), u1 = _mm256_shuffle_ps(t0, t2, 0xEE);
    __m256 u2 = _mm256_shuffle_ps(t1, t3, 0x44), u3 = _mm256_shuffle_ps(t1, t3, 0xEE);
    __m256 u4 = _mm256_shuffle_ps(t4, t6, 0x44), u5 = _mm256_shuffle_ps(t4, t6, 0xEE);
    __m256 u6 = _mm256_shuffle_ps(t5, t7, 0x44), u7 = _mm256_shuffle_ps(t5, t7, 0xEE);
    o[0] = _mm256_permute2f128_ps(u0, u4, 0x20);
    o[1] = _mm256_permute2f128_ps(u1, u5, 0x20);
    o[2] = _mm256_permute2f128_ps(u2, u6, 0x20);
    o[3] = _mm256_permute2f128_ps(u3, u7, 0x20);
    o[4] = _mm256_permute2f128_ps(u0, u4, 0x31);
    o[5] = _mm256_permute2f128_ps(u1, u5, 0x31);
    o[6] = _mm256_permute2f128_ps(u2, u6, 0x31);
    o[7] = _mm256_permute2f128_ps(u3, u7, 0x31);
}
#endif

/* Pack a full MR-row panel: dst[k*MR + r] = rows[r][k], k in [0, kc). */
static inline void pack_full(const float *const *rows, float *dst, int kc)
{
    int k = 0;
#ifdef __AVX__
#if MR == 12
    const float *ra[8] = {rows[0], rows[1], rows[2], rows[3],
                          rows[4], rows[5], rows[6], rows[7]};
    const float *rb[8] = {rows[8], rows[9], rows[10], rows[11],
                          rows[8], rows[9], rows[10], rows[11]};
    for (; k + 8 <= kc; k += 8) {
        __m256 o[8], q[8];
        tr8(ra, k, o);
        tr8(rb, k, q);
        float *d = dst + (size_t)k * MR;
        for (int j = 0; j < 8; j++) {
            _mm256_storeu_ps(d + j * MR, o[j]);
            _mm_storeu_ps(d + j * MR + 8, _mm256_castps256_ps128(q[j]));
        }
    }
#else
    const float *ra[8] = {rows[0], rows[1], rows[2], rows[3],
                          rows[4], rows[5], rows[0], rows[1]};
    for (; k + 8 <= kc; k += 8) {
        __m256 o[8];
        tr8(ra, k, o);
        float *d = dst + (size_t)k * MR;
        for (int j = 0; j < 8; j++) {
            _mm_storeu_ps(d + j * MR, _mm256_castps256_ps128(o[j]));
            _mm_storel_pi((__m64 *)(d + j * MR + 4), _mm256_extractf128_ps(o[j], 1));
        }
    }
#endif
#endif
    for (; k < kc; k++) {
        float *d = dst + (size_t)k * MR;
        for (int r = 0; r < MR; r++) d[r] = rows[r][k];
    }
}

static inline void store_edge_row(float *c, const float *t, int nr, int accum)
{
#if defined(__AVX512F__)
    __mmask16 m0 = nr >= 16 ? (__mmask16)0xFFFF : (__mmask16)((1u << nr) - 1);
    int r1 = nr - 16;
    __mmask16 m1 = r1 <= 0 ? (__mmask16)0 :
                   (r1 >= 16 ? (__mmask16)0xFFFF : (__mmask16)((1u << r1) - 1));
    __m512 v0 = _mm512_load_ps(t), v1 = _mm512_load_ps(t + 16);
    if (accum) {
        v0 = _mm512_add_ps(v0, _mm512_maskz_loadu_ps(m0, c));
        v1 = _mm512_add_ps(v1, _mm512_maskz_loadu_ps(m1, c + 16));
    }
    _mm512_mask_storeu_ps(c, m0, v0);
    _mm512_mask_storeu_ps(c + 16, m1, v1);
#elif defined(__AVX2__)
    __m256i iota = _mm256_setr_epi32(0, 1, 2, 3, 4, 5, 6, 7);
    __m256i m0 = _mm256_cmpgt_epi32(_mm256_set1_epi32(nr), iota);
    __m256i m1 = _mm256_cmpgt_epi32(_mm256_set1_epi32(nr - 8), iota);
    __m256 v0 = _mm256_load_ps(t), v1 = _mm256_load_ps(t + 8);
    if (accum) {
        v0 = _mm256_add_ps(v0, _mm256_maskload_ps(c, m0));
        v1 = _mm256_add_ps(v1, _mm256_maskload_ps(c + 8, m1));
    }
    _mm256_maskstore_ps(c, m0, v0);
    _mm256_maskstore_ps(c + 8, m1, v1);
#else
    if (accum) for (int j = 0; j < nr; j++) c[j] += t[j];
    else for (int j = 0; j < nr; j++) c[j] = t[j];
#endif
}

static inline void kernel(int kc, const float *restrict a, const float *restrict b,
                          float *restrict c, int ldc, int mr, int nr, int accum)
{
#define DECL(i) V c##i##0 = {0}, c##i##1 = {0};
    FOR_ROWS(DECL)
#undef DECL

#define FMA(i) { V a_ = (V){0} + a[i]; c##i##0 += a_ * b0; c##i##1 += a_ * b1; }
#define BODY { V b0 = *(const V *)(b); V b1 = *(const V *)(b + VW); \
               FOR_ROWS(FMA) a += MR; b += NR; }

    int k1 = kc - 24;
    if (k1 < 0) k1 = 0;
    int k = 0;
#pragma GCC unroll 4
    for (; k < k1; k++) BODY

    /* Bring the C tile in just before the stores. */
    for (int i = 0; i < mr; i++) {
        __builtin_prefetch(c + (size_t)i * ldc, 1, 3);
        __builtin_prefetch(c + (size_t)i * ldc + NR - 1, 1, 3);
    }

#pragma GCC unroll 4
    for (; k < kc; k++) BODY
#undef BODY
#undef FMA

    if (mr == MR && nr == NR) {
        if (accum) {
#define ST(i) { *(VU *)(c + (size_t)(i) * ldc) += c##i##0; \
                *(VU *)(c + (size_t)(i) * ldc + VW) += c##i##1; }
            FOR_ROWS(ST)
#undef ST
        } else {
#define ST(i) { *(VU *)(c + (size_t)(i) * ldc) = c##i##0; \
                *(VU *)(c + (size_t)(i) * ldc + VW) = c##i##1; }
            FOR_ROWS(ST)
#undef ST
        }
    } else {
        float t[MR * NR] __attribute__((aligned(64)));
#define ST(i) { *(V *)(t + (i) * NR) = c##i##0; *(V *)(t + (i) * NR + VW) = c##i##1; }
        FOR_ROWS(ST)
#undef ST
        for (int i = 0; i < mr; i++)
            store_edge_row(c + (size_t)i * ldc, t + i * NR, nr, accum);
    }
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;

    int npA = (n + MR - 1) / MR, npB = (n + NR - 1) / NR;
    size_t Mpad = (size_t)npA * MR, Npad = (size_t)npB * NR;

    /* Single K block for n <= KCMAX; otherwise balanced blocks, multiple of 8. */
    int nkb = (n + KCMAX - 1) / KCMAX;
    int KCB = (n + nkb - 1) / nkb;
    KCB = (KCB + 7) & ~7;
    nkb = (n + KCB - 1) / KCB;

    sA = grow(sA, &capA, Mpad * n);
    sB = grow(sB, &capB, Npad * n);
    float *Ap = sA, *Bp = sB;

    int T = omp_get_max_threads();
    if (T < 1) T = 1;
    int mcp = MCP, ncp = NCP;
    int nib = (npA + mcp - 1) / mcp;
    int njb = (npB + ncp - 1) / ncp;
    while (nib * njb < 4 * T && ncp > 1) {
        ncp /= 2;
        njb = (npB + ncp - 1) / ncp;
    }
    while (nib * njb < 4 * T && mcp > 4) {
        mcp /= 2;
        nib = (npA + mcp - 1) / mcp;
    }
    int npan = npA + npB;

    #pragma omp parallel
    {
        /* Pack A row panels and B column panels, per K block. */
        #pragma omp for schedule(dynamic, 1)
        for (int t = 0; t < nkb * npan; t++) {
            int kb = t / npan, u = t % npan;
            int pc = kb * KCB;
            int kc = n - pc < KCB ? n - pc : KCB;
            if (u < npA) {
                int p = u;
                float *dst = Ap + (size_t)pc * Mpad + (size_t)p * MR * kc;
                int r0 = p * MR;
                int h = n - r0 < MR ? n - r0 : MR;
                const float *src = A + (size_t)r0 * n + pc;
                if (h == MR) {
                    const float *rows[MR];
                    for (int r = 0; r < MR; r++) rows[r] = src + (size_t)r * n;
                    pack_full(rows, dst, kc);
                } else {
                    for (int k = 0; k < kc; k++) {
                        float *d = dst + (size_t)k * MR;
                        int r;
                        for (r = 0; r < h; r++) d[r] = src[(size_t)r * n + k];
                        for (; r < MR; r++) d[r] = 0.0f;
                    }
                }
            } else {
                int jp = u - npA;
                float *dst = Bp + (size_t)pc * Npad + (size_t)jp * NR * kc;
                int j0 = jp * NR;
                int w = n - j0 < NR ? n - j0 : NR;
                for (int k = 0; k < kc; k++) {
                    const float *src = B + (size_t)(pc + k) * n + j0;
                    float *d = dst + (size_t)k * NR;
                    if (w == NR) {
                        memcpy(d, src, NR * sizeof(float));
                    } else {
                        int j;
                        for (j = 0; j < w; j++) d[j] = src[j];
                        for (; j < NR; j++) d[j] = 0.0f;
                    }
                }
            }
        }

        #pragma omp for schedule(dynamic, 1)
        for (int t = 0; t < nib * njb; t++) {
            int ib = t / njb, jb = t % njb;
            int p0 = ib * mcp, p1 = p0 + mcp < npA ? p0 + mcp : npA;
            int q0 = jb * ncp, q1 = q0 + ncp < npB ? q0 + ncp : npB;
            for (int kb = 0; kb < nkb; kb++) {
                int pc = kb * KCB;
                int kc = n - pc < KCB ? n - pc : KCB;
                int accum = kb > 0;
                const float *abase = Ap + (size_t)pc * Mpad;
                const float *bbase = Bp + (size_t)pc * Npad;
                for (int p = p0; p < p1; p++) {
                    int r0 = p * MR;
                    int mr = n - r0 < MR ? n - r0 : MR;
                    const float *ap = abase + (size_t)p * MR * kc;
                    for (int q = q0; q < q1; q++) {
                        int j0 = q * NR;
                        int nr = n - j0 < NR ? n - j0 : NR;
                        kernel(kc, ap, bbase + (size_t)q * NR * kc,
                               C + (size_t)r0 * n + j0, n, mr, nr, accum);
                    }
                }
            }
        }
    }
}
